def solve_game(N):
    # W[n] = True if the player whose turn it is at n wins (N-position)
    # W[n] = False if the player whose turn it is at n loses (P-position)
    W = {}

    # Iterate backwards from N-1 to 1
    for n in range(N - 1, 0, -1):
        can_win = False

        # Check move n+1
        n_plus_1 = n + 1
        if n_plus_1 <= N:
            if n_plus_1 == N:
                # Reaching N is an immediate win
                can_win = True
            else:
                # If the successor state (n+1) is Losing (False), we win
                if not W.get(n_plus_1):
                    can_win = True

        # Check move 2n
        n_times_2 = 2 * n
        if n_times_2 <= N:
            if n_times_2 == N:
                # Reaching N is an immediate win
                can_win = True
            else:
                # If the successor state (2n) is Losing (False), we win
                if not W.get(n_times_2):
                    can_win = True

        W[n] = can_win

    # B is the first mover from n=1.
    # N is Type B (B wins) if W[1] is True.
    return W.get(1, False)

# Search for the least N > 400 such that it is Type B (returns True)
N_start = 401
found_N = None

# We must search up to a reasonable limit, checking intervals of 100 might be enough
# given the exponential nature of moves.
print("Searching for Type B N > 400...")
for N in range(N_start, 1000):
